import { getAuthToken } from '@linm-soft-org/linm-web-common-components';

const GUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function normCompanyCode(value: string): string {
  return value.trim().toUpperCase();
}

function decodeJwtPayload(token: string): Record<string, unknown> | null {
  try {
    const part = token.split('.')[1];
    if (!part) return null;
    const base64 = part.replace(/-/g, '+').replace(/_/g, '/');
    const padded = base64.padEnd(base64.length + ((4 - (base64.length % 4)) % 4), '=');
    return JSON.parse(atob(padded)) as Record<string, unknown>;
  } catch {
    return null;
  }
}

/** JWT home tenant (`company_id`) — SSOT over stale secure-storage user blob. */
export function readJwtHomeCompanyId(): string | undefined {
  const token = getAuthToken();
  if (!token) return undefined;
  const payload = decodeJwtPayload(token);
  const raw = payload?.company_id;
  if (typeof raw !== 'string' || !raw.trim()) return undefined;
  const code = normCompanyCode(raw);
  return GUID_RE.test(code) ? undefined : code;
}

export interface JwtTenantScope {
  canViewAll: boolean;
  allowedCompanyIds: string[];
}

/** JWT `allowed_company_ids` — codes only (Guid entries skipped at boundary). */
export function readJwtTenantScope(): JwtTenantScope {
  const token = getAuthToken();
  if (!token) return { canViewAll: false, allowedCompanyIds: [] };

  const payload = decodeJwtPayload(token);
  const raw = payload?.allowed_company_ids;
  if (typeof raw !== 'string' || !raw.trim()) {
    return { canViewAll: false, allowedCompanyIds: [] };
  }

  if (raw.trim() === '*') {
    return { canViewAll: true, allowedCompanyIds: [] };
  }

  const allowedCompanyIds = raw
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part && !GUID_RE.test(part))
    .map(normCompanyCode);

  return { canViewAll: false, allowedCompanyIds };
}
