import React, { useEffect, type FC, type ReactNode } from 'react';
import {
  getAuthUser,
  hasValidAuthToken,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../store/hooks';
import { setUser } from '../store/slices/authSlice';
import { isStandalone } from '../dev/isStandalone';

/**
 * Sync Redux auth slice from secure storage (Home login / shell refresh).
 * Tenant reconcile runs in TenantBootstrapGate — not here (NavAuthHydrate parity).
 */
export const AuthHydrate: FC<{ children: ReactNode }> = ({ children }) => {
  const dispatch = useAppDispatch();

  useEffect(() => {
    if (isStandalone) return;

    const sync = () => {
      if (!hasValidAuthToken()) return;
      const stored = getAuthUser();
      if (stored) dispatch(setUser(stored));
    };

    sync();
    window.addEventListener('linm:auth:changed', sync);
    window.addEventListener('linm:auth:token-changed', sync);

    return () => {
      window.removeEventListener('linm:auth:changed', sync);
      window.removeEventListener('linm:auth:token-changed', sync);
    };
  }, [dispatch]);

  return <>{children}</>;
};