import {
  clearActiveCompanyId,
  getActiveCompanyId,
  getAuthUser,
  setAuthUser,
  normCompanyCode,
} from '@linm-soft-org/linm-web-common-components';
import type { User } from '../models/User';
import { appSettings } from '../config/appSettings';
import { readJwtHomeCompanyId, readJwtTenantScope } from './jwtTenantClaims';
import { getAuthToken } from '@linm-soft-org/linm-web-common-components';
import { validateAndGetActiveCompanyId } from './activeCompanyValidate';

function hasAuthToken(): boolean {
  return Boolean(getAuthToken());
}

function sortedAllowedCodes(ids: string[] | undefined): string[] {
  return [...(ids ?? []).map(normCompanyCode)].sort();
}

function sameAllowedCompanyIds(a: string[] | undefined, b: string[] | undefined): boolean {
  const left = sortedAllowedCodes(a);
  const right = sortedAllowedCodes(b);
  return left.length === right.length && left.every((code, i) => code === right[i]);
}

function tenantScopeMatches(
  user: User,
  jwtHome: string,
  jwtScope: ReturnType<typeof readJwtTenantScope>,
): boolean {
  const homeOk = normCompanyCode(user.companyId ?? '') === jwtHome;
  const canViewAllOk = user.canViewAllCompanies === jwtScope.canViewAll;
  const expectedAllowed = jwtScope.canViewAll
    ? user.allowedCompanyIds
    : jwtScope.allowedCompanyIds.length > 0
      ? jwtScope.allowedCompanyIds.map(normCompanyCode)
      : [jwtHome];
  const allowedOk = sameAllowedCompanyIds(user.allowedCompanyIds, expectedAllowed);
  return homeOk && canViewAllOk && allowedOk;
}

/** When JWT is present, sync secure-storage user blob before scope resolve (TENANT-P1-03). */
function syncUserHomeFromJwt(user: User | null | undefined): User | null | undefined {
  if (!hasAuthToken()) return user ?? getAuthUser();

  const jwtHome = readJwtHomeCompanyId();
  const jwtScope = readJwtTenantScope();
  const scopedUser = user ?? getAuthUser();
  if (!jwtHome || !scopedUser) return scopedUser;

  if (tenantScopeMatches(scopedUser, jwtHome, jwtScope)) {
    return scopedUser;
  }

  const updated: User = {
    ...scopedUser,
    companyId: jwtHome,
    allowedCompanyIds: jwtScope.canViewAll
      ? scopedUser.allowedCompanyIds
      : jwtScope.allowedCompanyIds.length > 0
        ? jwtScope.allowedCompanyIds.map(normCompanyCode)
        : [jwtHome],
    canViewAllCompanies: jwtScope.canViewAll,
  };
  setAuthUser(updated);
  return updated;
}

/** Dev + prod — warn when JWT home ≠ active storage (stale X-Company-Id). */
export function logTenantDiagnostics(): void {
  if (typeof window === 'undefined') return;

  const validation = validateAndGetActiveCompanyId();
  const apiUrl = appSettings.apiUrl;
  const onLocalhost =
    window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';

  if (appSettings.isDev && onLocalhost && apiUrl?.includes('bff.linm-soft.com')) {
    console.warn(
      '[tenant] Local UI but API URL is production BFF. Open http://localhost:8504 (yarn start:std) or fix .env VITE_API_URL.',
      { apiUrl },
    );
  }

  if (
    validation.jwtHome &&
    validation.stored &&
    validation.jwtHome !== validation.stored
  ) {
    console.warn('[tenant] X-Company-Id differs from JWT company_id — reconciling', {
      stored: validation.stored,
      jwtHome: validation.jwtHome,
      allowed: validation.allowedCompanyIds,
      canViewAll: validation.canViewAll,
      corrected: validation.corrected,
      apiUrl,
    });
  }
}

/**
 * Align `linm_active_company_id` with JWT scope.
 * SSOT validate: validateAndGetActiveCompanyId (not resolveInitialActiveCompanyId alone).
 */
export function reconcileActiveCompanyForUser(user: User | null | undefined): void {
  logTenantDiagnostics();
  syncUserHomeFromJwt(user);

  const jwtHome = readJwtHomeCompanyId();
  if (hasAuthToken() && !jwtHome && getActiveCompanyId()) {
    clearActiveCompanyId();
    return;
  }

  validateAndGetActiveCompanyId();
}
